mqd_t mqdes;
const char *q_name = "/ref_queue";
mode_t mode = 0644;

// Message Queue Attributes (required for O_CREAT)
struct mq_attr attr = {
    .mq_maxmsg = 10,
    .mq_msgsize = 1024
};

// 1. Open an existing queue for read/write (blocking default)
mqdes = mq_open(q_name, O_RDWR);

// 2. Create a new queue (O_CREAT) with permissions
// Must supply mode (0644) and attributes (&attr)
mqdes = mq_open(q_name,
                O_CREAT | O_EXCL | O_RDWR,
                mode,
                &attr);

// Handle error: mqdes == (mqd_t)-1 on failure
// Remember to call mq_close() later
// And mq_unlink() to remove the queue name
// mq_close(mqdes);
